import json
from itertools import permutations

def solve():
    houses = [1, 2, 3, 4]  # indices 0..3 represent houses 1..4

    # Attributes
    Names = ['Peter', 'Alice', 'Eric', 'Arnold']
    Hobbies = ['cooking', 'painting', 'gardening', 'photography']
    Animals = ['horse', 'fish', 'cat', 'bird']
    Books = ['fantasy', 'mystery', 'romance', 'science fiction']
    Months = ['april', 'jan', 'sept', 'feb']
    Music = ['pop', 'rock', 'classical', 'jazz']

    idx = lambda perm, v: perm.index(v)

    solution = None

    # Iterate with pruning at each stage
    for books in permutations(Books):
        # Clue 4: The person who loves romance books is not in the fourth house.
        if books[3] == 'romance':
            continue

        for hobbies in permutations(Hobbies):
            # Clue 15: The person who loves cooking is not in the third house. (index 2)
            if hobbies[2] == 'cooking':
                continue
            # Clue 1 and 9: cooking = romance and jazz = cooking -> cooking aligns with romance; will check jazz later.
            if idx(hobbies, 'cooking') != idx(books, 'romance'):
                continue
            # Clue 11: The person who paints is directly left of the person who loves romance books.
            if idx(hobbies, 'painting') + 1 != idx(books, 'romance'):
                continue

            for music in permutations(Music):
                # Clue 9: jazz = cooking
                if idx(music, 'jazz') != idx(hobbies, 'cooking'):
                    continue
                # Clue 10: rock = mystery
                if idx(music, 'rock') != idx(books, 'mystery'):
                    continue

                for months in permutations(Months):
                    # Clue 2: feb = pop
                    if idx(months, 'feb') != idx(music, 'pop'):
                        continue
                    # Clue 8: gardening = april
                    if idx(hobbies, 'gardening') != idx(months, 'april'):
                        continue
                    # Clue 14: rock is directly left of jan
                    if idx(music, 'rock') + 1 != idx(months, 'jan'):
                        continue

                    for animals in permutations(Animals):
                        # Clue 5: feb = fish
                        if idx(months, 'feb') != idx(animals, 'fish'):
                            continue
                        # Clue 7: horse = rock
                        if idx(animals, 'horse') != idx(music, 'rock'):
                            continue
                        # Clue 16: cat is somewhere to the right of horse
                        if not (idx(animals, 'cat') > idx(animals, 'horse')):
                            continue

                        for names in permutations(Names):
                            # Clue 3: Eric is not in the second house.
                            if names[1] == 'Eric':
                                continue
                            # Clue 12: Peter = pop
                            if idx(names, 'Peter') != idx(music, 'pop'):
                                continue
                            # Clue 13: gardening = Arnold
                            if idx(hobbies, 'gardening') != idx(names, 'Arnold'):
                                continue
                            # Clue 6: Alice is somewhere to the right of fantasy
                            if not (idx(names, 'Alice') > idx(books, 'fantasy')):
                                continue

                            # All constraints satisfied
                            solution = {
                                "books": books,
                                "hobbies": hobbies,
                                "music": music,
                                "months": months,
                                "animals": animals,
                                "names": names
                            }
                            break
                        if solution:
                            break
                    if solution:
                        break
                if solution:
                    break
            if solution:
                break
        if solution:
            break

    if not solution:
        raise RuntimeError("No solution found")

    # Build output JSON
    header = ["House", "Name", "hobby", "animals", "favorite book genres", "birthday month", "favorite music genres"]
    rows = []
    for i in range(4):
        row = [
            str(i + 1),
            solution["names"][i],
            solution["hobbies"][i],
            solution["animals"][i],
            solution["books"][i],
            solution["months"][i],
            solution["music"][i],
        ]
        rows.append(row)

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    solve()
